content:
{
  "test_cases": [
    {
      "id": "TC-055-01",
      "title": "MA request includes all applicable reasons",
      "covers": [
        "ETC-055"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in a state where an MA request is triggered. Multiple MA request reasons are applicable simultaneously (e.g., train front passes perturbation location and Section timer expires).",
      "test_inputs": "Configuration with multiple applicable MA request reasons.",
      "assumptions": "The specific reasons are defined in SUBSET-026 §3.8.2.1.1. The test environment allows monitoring of the MA request message content.",
      "steps": [
        {
          "no": 1,
          "action": "Trigger an MA request while multiple MA request reasons are applicable.",
          "expected": "The OBU sends an MA request to the RBC."
        },
        {
          "no": 2,
          "action": "Inspect the content of the sent MA request message.",
          "expected": "The message includes all applicable MA request reasons as defined in SUBSET-026 §3.8.2.1.1."
        }
      ]
    },
    {
      "id": "TC-055-02",
      "title": "MA request includes single applicable reason",
      "covers": [
        "ETC-055"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "OBU is in a state where an MA request is triggered. Only one MA request reason is applicable.",
      "test_inputs": "Configuration with a single applicable MA request reason.",
      "assumptions": "The specific reason is defined in SUBSET-026 §3.8.2.1.1.",
      "steps": [
        {
          "no": 1,
          "action": "Trigger an MA request while only one MA request reason is applicable.",
          "expected": "The OBU sends an MA request to the RBC."
        },
        {
          "no": 2,
          "action": "Inspect the content of the sent MA request message.",
          "expected": "The message includes the single applicable MA request reason."
        }
      ]
    },
    {
      "id": "ETC-056-01",
      "title": "MA request triggered by perturbation-location criterion",
      "covers": [
        "ETC-056"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is receiving movement authority. The perturbation-location criterion is defined in SUBSET-026 §3.8.2.2.1. The train is moving towards the calculated location.",
      "test_inputs": "Train position data simulating passage of the perturbation location.",
      "assumptions": "The perturbation-location criterion calculation is correctly implemented as per SUBSET-026 §3.8.2.2.1.",
      "steps": [
        {
          "no": 1,
          "action": "Move the train front to the location resulting from the perturbation-location criterion.",
          "expected": "The OBU triggers an MA request to the RBC."
        }
      ]
    },
    {
      "id": "ETC-056-02",
      "title": "MA request triggered by Section timer/LOA speed timer criterion",
      "covers": [
        "ETC-056"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is receiving movement authority. The Section timer/LOA speed timer criterion is defined in SUBSET-026 §3.8.2.2.1. The timer is running.",
      "test_inputs": "Time simulation to reach the timer limit.",
      "assumptions": "The Section timer/LOA speed timer criterion calculation is correctly implemented as per SUBSET-026 §3.8.2.2.1.",
      "steps": [
        {
          "no": 1,
          "action": "Wait until the moment resulting from the Section timer/LOA speed timer criterion is reached.",
          "expected": "The OBU triggers an MA request to the RBC."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "Safe radio connection loss triggers immediate reconnection attempt",
      "covers": [
        "ETC-010"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in an established communication session with a specific radio system (e.g., GSM-R). EURORADIO is active.",
      "test_inputs": "Simulated loss of safe radio connection signal from EURORADIO.",
      "assumptions": "The radio system previously used for the successful connection is available and functional.",
      "steps": [
        {
          "no": 1,
          "action": "Establish a safe radio connection with Radio System A.",
          "expected": "OBU status indicates an active safe radio connection with Radio System A."
        },
        {
          "no": 2,
          "action": "Simulate EURORADIO reporting the loss of the safe radio connection.",
          "expected": "OBU immediately initiates an attempt to set up a new safe radio connection with Radio System A."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "Repeated reconnection attempts until success",
      "covers": [
        "ETC-011"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in an established communication session. The safe radio connection has been lost.",
      "test_inputs": "Simulated failure of first reconnection attempt, followed by success on the second attempt.",
      "assumptions": "The session is not terminated and the train has not passed the RIU termination location.",
      "steps": [
        {
          "no": 1,
          "action": "Simulate the loss of the safe radio connection.",
          "expected": "OBU starts the reconnection process."
        },
        {
          "no": 2,
          "action": "Simulate the failure of the first reconnection attempt.",
          "expected": "OBU continues to attempt to set up a new safe radio connection."
        },
        {
          "no": 3,
          "action": "Simulate the success of the second reconnection attempt.",
          "expected": "A new safe radio connection is established, and the reconnection attempts stop."
        }
      ]
    },
    {
      "id": "TC-03",
      "title": "Reconnection attempts stop when session is terminated",
      "covers": [
        "ETC-011"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "OBU is in an established communication session. The safe radio connection has been lost and reconnection attempts are ongoing.",
      "test_inputs": "Signal indicating the communication session is regarded as terminated.",
      "assumptions": "The train has not passed the RIU termination location.",
      "steps": [
        {
          "no": 1,
          "action": "Simulate the loss of the safe radio connection.",
          "expected": "OBU starts reconnection attempts."
        },
        {
          "no": 2,
          "action": "Simulate that the communication session is regarded as terminated.",
          "expected": "OBU stops repeating attempts to set up a new safe radio connection."
        }
      ]
    },
    {
      "id": "TC-04",
      "title": "Reconnection attempts stop when train passes RIU termination location",
      "covers": [
        "ETC-011"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "OBU is in an established communication session. The safe radio connection has been lost and reconnection attempts are ongoing. An RIU order specifying a termination location is active.",
      "test_inputs": "Train position data indicating the train has passed the location given in the RIU order.",
      "assumptions": "The session is not otherwise terminated.",
      "steps": [
        {
          "no": 1,
          "action": "Simulate the loss of the safe radio connection.",
          "expected": "OBU starts reconnection attempts."
        },
        {
          "no": 2,
          "action": "Simulate the train passing the location specified in the RIU order to terminate the communication session.",
          "expected": "OBU stops repeating attempts to set up a new safe radio connection."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-ETC-050-01",
      "title": "MA uzunluğunu tam kapsamayan SSP/gradient ile MA kabul edilmemesi",
      "covers": [
        "ETC-050"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "OBU, MA işleme modundadır. Araçta mevcut SSP ve gradient verileri, gelen MA'nın tam uzunluğunu kapsamayacak şekilde yapılandırılmıştır.",
      "test_inputs": "Gelen MA mesajı: Uzunluk 1000m. Mevcut SSP/gradient kapsamı: 0-800m (200m eksik).",
      "assumptions": "SUBSET-026 §3.7.2.3.1–3.7.2.3.2'de tanımlanan 'tam uzunluk' kriteri, SSP ve gradient verilerinin MA'nın başlangıcından bitişine kadar kesintisiz olarak mevcut olmasını gerektirir.",
      "steps": [
        {
          "no": 1,
          "action": "Uzunluğu 1000m olan bir MA ve bu MA'nın tam uzunluğunu kapsamayan (0-800m) SSP/gradient verisi OBU'ya iletilir.",
          "expected": "OBU, MA'yı ve ilişkili mod profillerini kabul etmez. MA reddedilir veya işlenmez."
        },
        {
          "no": 2,
          "action": "OBU'nun MA kabul durumu kontrol edilir.",
          "expected": "OBU, MA'yı aktif olarak uygulamaz ve sürücüye ilgili hata/uyarı durumunu gösterir (varsa)."
        }
      ]
    },
    {
      "id": "TC-ETC-050-02",
      "title": "MA uzunluğunu tam kapsayan SSP/gradient ile MA kabul edilmesi",
      "covers": [
        "ETC-050"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU, MA işleme modundadır. Araçta mevcut SSP ve gradient verileri, gelen MA'nın tam uzunluğunu kapsamaktadır.",
      "test_inputs": "Gelen MA mesajı: Uzunluk 1000m. Mevcut SSP/gradient kapsamı: 0-1000m (Tam kapsam).",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Uzunluğu 1000m olan bir MA ve bu MA'nın tam uzunluğunu kapsayan (0-1000m) SSP/gradient verisi OBU'ya iletilir.",
          "expected": "OBU, MA'yı ve ilişkili mod profillerini kabul eder."
        },
        {
          "no": 2,
          "action": "OBU'nun MA kabul durumu kontrol edilir.",
          "expected": "OBU, MA'yı aktif olarak uygulamaya başlar."
        }
      ]
    },
    {
      "id": "TC-ETC-050-03",
      "title": "MA ile birlikte gelen SSP/gradient'in MA uzunluğunu tam kapsamaması",
      "covers": [
        "ETC-050"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "OBU, MA işleme modundadır. Araçta mevcut SSP/gradient verileri MA'dan önceki bölgeyi kapsamaktadır ancak MA ile birlikte gelen yeni SSP/gradient verisi MA'nın tam uzunluğunu kapsamamaktadır.",
      "test_inputs": "Gelen MA mesajı: Uzunluk 500m. MA ile birlikte gelen SSP/gradient kapsamı: 0-400m (100m eksik).",
      "assumptions": "MA ile birlikte gelen SSP/gradient verisi, araçtaki mevcut verileri günceller veya tamamlayıcı olarak değerlendirilir. 'Tam uzunluk' kriteri, MA'nın tamamı için geçerli veri bulunmasını gerektirir.",
      "steps": [
        {
          "no": 1,
          "action": "Uzunluğu 500m olan bir MA ve bu MA ile birlikte gelen, MA'nın tam uzunluğunu kapsamayan (0-400m) SSP/gradient verisi OBU'ya iletilir.",
          "expected": "OBU, MA'yı ve ilişkili mod profillerini kabul etmez."
        },
        {
          "no": 2,
          "action": "OBU'nun MA kabul durumu kontrol edilir.",
          "expected": "OBU, MA'yı aktif olarak uygulamaz."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "OBU initiates termination upon explicit trackside order",
      "covers": [
        "ETC-012"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "An active communication session is established between the OBU and the trackside (RBC).",
      "test_inputs": "Trackside sends a 'Termination of Communication Session' message.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Establish a communication session between the OBU and the RBC.",
          "expected": "The OBU confirms the session establishment."
        },
        {
          "no": 2,
          "action": "Send a 'Termination of Communication Session' message from the trackside to the OBU.",
          "expected": "The OBU initiates the termination of the communication session."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "OBU does not initiate termination without trackside order or defined condition",
      "covers": [
        "ETC-012"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "An active communication session is established between the OBU and the trackside (RBC).",
      "test_inputs": "No termination message from trackside; no termination conditions from SUBSET-026 are met.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Establish a communication session between the OBU and the RBC.",
          "expected": "The OBU confirms the session establishment."
        },
        {
          "no": 2,
          "action": "Wait for a duration sufficient to rule out timeout-based termination, without sending any termination order from the trackside and without fulfilling any other termination conditions.",
          "expected": "The OBU maintains the communication session and does not initiate termination."
        }
      ]
    },
    {
      "id": "TC-03",
      "title": "OBU repeats Termination message if no acknowledgement is received",
      "covers": [
        "ETC-013"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "An active communication session is established. The OBU has initiated termination (e.g., via trackside order).",
      "test_inputs": "Trackside does not send an acknowledgement for the 'Termination of Communication Session' message.",
      "assumptions": "The fixed waiting time defined in SUBSET-026 Appendix A.3.1 is known and configurable for testing.",
      "steps": [
        {
          "no": 1,
          "action": "Initiate the termination of the communication session from the OBU.",
          "expected": "The OBU sends the 'Termination of Communication Session' message."
        },
        {
          "no": 2,
          "action": "Wait for the fixed waiting time defined in SUBSET-026 Appendix A.3.1 without sending an acknowledgement from the trackside.",
          "expected": "The OBU repeats the 'Termination of Communication Session' message."
        },
        {
          "no": 3,
          "action": "Wait for the fixed waiting time again without sending an acknowledgement.",
          "expected": "The OBU repeats the 'Termination of Communication Session' message a second time."
        }
      ]
    },
    {
      "id": "TC-04",
      "title": "OBU stops repeating Termination message upon receiving acknowledgement",
      "covers": [
        "ETC-013"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "An active communication session is established. The OBU has initiated termination and is in the process of repeating the message due to lack of acknowledgement.",
      "test_inputs": "Trackside sends an acknowledgement after the first repetition.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Initiate the termination of the communication session from the OBU.",
          "expected": "The OBU sends the 'Termination of Communication Session' message."
        },
        {
          "no": 2,
          "action": "Wait for the fixed waiting time without acknowledgement, causing the OBU to repeat the message.",
          "expected": "The OBU sends the repeated 'Termination of Communication Session' message."
        },
        {
          "no": 3,
          "action": "Send an acknowledgement from the trackside to the OBU.",
          "expected": "The OBU stops repeating the 'Termination of Communication Session' message."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-015-01",
      "title": "Güç açıldığında GSM-R kayıt emrinin verilmesi",
      "covers": [
        "ETC-015"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU kapalı durumdadır. GSM-R Mobil Terminal bağlıdır.",
      "test_inputs": "",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "OBU güç açma (power-up) komutu verilir.",
          "expected": "OBU, bağlı GSM-R Mobil Terminal'in GSM-R Radyo Ağı'na kaydolması için emir verir."
        }
      ]
    },
    {
      "id": "TC-015-02",
      "title": "Sürücü yeni GSM-R Radyo Ağı kimliği girdiğinde kayıt emrinin verilmesi",
      "covers": [
        "ETC-015"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU çalışır durumdadır. Sürücü arayüzü erişilebilir.",
      "test_inputs": "Yeni GSM-R Radyo Ağı kimliği (örn: 901)",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Sürücü, arayüz üzerinden yeni bir GSM-R Radyo Ağı kimliği girer ve onaylar.",
          "expected": "OBU, bağlı GSM-R Mobil Terminal'in yeni girilen GSM-R Radyo Ağı'na kaydolması için emir verir."
        }
      ]
    },
    {
      "id": "TC-015-03",
      "title": "Yol kenarı emriyle GSM-R kayıt emrinin verilmesi",
      "covers": [
        "ETC-015"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU çalışır durumdadır. Yol kenarı ile iletişim kurulabilir.",
      "test_inputs": "Yol kenarından gelen kayıt emri mesajı",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Yol kenarı, OBU'ya GSM-R kayıt emri gönderir.",
          "expected": "OBU, bağlı GSM-R Mobil Terminal'in GSM-R Radyo Ağı'na kaydolması için emir verir."
        }
      ]
    },
    {
      "id": "TC-016-01",
      "title": "Hafızada Radyo Ağı tipi yokken varsayılan tipin kullanılması",
      "covers": [
        "ETC-016"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU hafızasında Radyo Ağı tipi bulunmamaktadır (ilk güç açılışı veya Sistem Arızası sonrası). Araca yüklü varsayılan Radyo Ağı tipi yapılandırılmıştır.",
      "test_inputs": "",
      "assumptions": "Varsayılan Radyo Ağı tipi 'GSM-R' olarak yapılandırılmıştır.",
      "steps": [
        {
          "no": 1,
          "action": "OBU güç açılır ve Radyo Ağı tipi sorgulanır.",
          "expected": "OBU, hafızada tip bulunmadığı için araçta yapılandırılmış varsayılan Radyo Ağı tipini kullanır."
        }
      ]
    },
    {
      "id": "TC-017-01",
      "title": "Kayıtlı olmayan radyo sistemi için güvenli bağlantı isteğinin yapılmaması",
      "covers": [
      "ETC-017"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "OBU çalışır durumdadır. Depolanan Radyo Ağı tipi 'GSM-R' olarak ayarlanmıştır. Sürücü tek radyo seçimi olarak 'GSM-R' seçmiştir. GSM-R radyo sistemi, ilgili Radyo Ağı'na kayıtlı değildir.",
      "test_inputs": "Yol kenarından gelen RBC oturumu kurma emri",
      "assumptions": "GSM-R terminali ağa kayıtlı değildir (Registration status: Not Registered).",
      "steps": [
        {
          "no": 1,
          "action": "Yol kenarı, OBU'ya RBC ile oturum kurma emri gönderir.",
          "expected": "OBU, gerekli radyo sisteminin (GSM-R) Radyo Ağı'na kayıtlı olmaması nedeniyle güvenli radyo bağlantısı kurulumu isteğinde bulunmaz."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-ETC-026-01",
      "title": "Report train position to RBC referring to last passed compliant LRBG",
      "covers": [
        "ETC-026"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in operational mode. A compliant LRBG (linked and announced in linking) has been passed. The RBC is connected and ready to receive position reports.",
      "test_inputs": "Train position data, LRBG identification data.",
      "assumptions": "The specific conditions of SUBSET-026 §3.6.5.1.8 are met for the passed LRBG.",
      "steps": [
        {
          "no": 1,
          "action": "Pass a compliant LRBG (linked and announced in linking).",
          "expected": "OBU identifies the LRBG as compliant."
        },
        {
          "no": 2,
          "action": "Move the train to a new position.",
          "expected": "OBU calculates the current train position."
        },
        {
          "no": 3,
          "action": "Trigger a position report to the RBC.",
          "expected": "The position report sent to the RBC refers to the last passed compliant LRBG."
        }
      ]
    },
    {
      "id": "TC-ETC-026-02",
      "title": "Accept trackside information referring to recently reported LRBG",
      "covers": [
        "ETC-026"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU has reported a position to the RBC referring to a specific LRBG (LRBG_A). The minimum number of recently reported LRBGs is set according to SUBSET-026 §3.6.2.2.2 c).",
      "test_inputs": "Trackside information message referring to LRBG_A.",
      "assumptions": "LRBG_A is within the window of recently reported LRBGs defined by the minimum number setting.",
      "steps": [
        {
          "no": 1,
          "action": "Receive trackside information from the RBC that refers to LRBG_A.",
          "expected": "OBU accepts the trackside information."
        },
        {
          "no": 2,
          "action": "Verify the internal state of the OBU.",
          "expected": "The trackside information is processed and stored/used as valid."
        }
      ]
    },
    {
      "id": "TC-ETC-026-03",
      "title": "Reject trackside information referring to LRBG outside recent window",
      "covers": [
        "ETC-026"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "OBU has reported positions for several LRBGs. The minimum number of recently reported LRBGs is set to N. An LRBG (LRBG_OLD) was reported more than N times ago.",
      "test_inputs": "Trackside information message referring to LRBG_OLD.",
      "assumptions": "LRBG_OLD is not within the minimum number of recently reported LRBGs.",
      "steps": [
        {
          "no": 1,
          "action": "Receive trackside information from the RBC that refers to LRBG_OLD.",
          "expected": "OBU rejects the trackside information."
        },
        {
          "no": 2,
          "action": "Verify the internal state of the OBU.",
          "expected": "The trackside information is not processed or stored as valid."
        }
      ]
    },
    {
      "id": "TC-ETC-026-04",
      "title": "Report position referring to last passed LRBG when linking consistency is not checked",
      "covers": [
        "ETC-026"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "OBU is in operational mode. A LRBG (LRBG_UNLINKED) is not marked as unlinked (i.e., compliance is determined by 'not marked as unlinked'). This LRBG has been passed.",
      "test_inputs": "Train position data, LRBG identification data.",
      "assumptions": "The LRBG is not marked as unlinked, satisfying the compliance condition for this case.",
      "steps": [
        {
          "no": 1,
          "action": "Pass LRBG_UNLINKED.",
          "expected": "OBU identifies LRBG_UNLINKED as compliant based on the 'not marked as unlinked' condition."
        },
        {
          "no": 2,
          "action": "Trigger a position report to the RBC.",
          "expected": "The position report sent to the RBC refers to LRBG_UNLINKED."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "ETC-023: Geçersiz konumun LRBG geçişinde geçerli konumla değiştirilmesi",
      "covers": [
        "ETC-023"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU, tren konumunun geçersiz olduğunu raporlamaktadır. Araçta daha önce depolanmış geçersiz bir konum değeri bulunmaktadır.",
      "test_inputs": "LRBG geçiş sinyali.",
      "assumptions": "LRBG geçişinde OBU'nun geçerli bir konum hesaplayabildiği varsayılmaktadır.",
      "steps": [
        {
          "no": 1,
          "action": "Trenin LRBG'yi geçtiği simüle edilir.",
          "expected": "OBU, geçerli bir tren konumu depolar ve mevcut konum durumunu 'geçerli' olarak günceller."
        },
