      "title": "PBD computation uses EBD curve and specified assumptions",
      "covers": [
        "ETC-092"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in operational mode and receives permitted braking distance data requiring emergency brake usage.",
      "test_inputs": "Permitted braking distance data, train parameters (mass, gradient, etc.) consistent with SUBSET-026 §3.11.11.4 assumptions.",
      "assumptions": "The OBU is configured to use the calculation assumptions of SUBSET-026 §3.11.11.4.",
